float sdCircle( vec2 p, float r )
{
    return length(p) -r;
}
float sdFace( vec2 p, float r )
{
    p.y-= 1.5*mod(abs(0.33*p.x),0.5);
    return sdCircle(p, r);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;
	float d1 = sdFace(p,0.7);
    vec3 col = vec3(1.);
    col = (d1<0.0) ? vec3(0.9,0.1,0.3) : vec3(1.0);
    col *= exp(2.*abs(d1));
    col = mix( col, vec3(0.9,0.1,0.1), 1.0-smoothstep(0.0,0.01,abs(d1)) );

    // Output to screen
    fragColor = vec4(col,1.0);
}
